    # Choose the most central uniform row or column as the separator.
    candidates = []
    for r in range(h):
        if len(set(grid[r])) == 1 and 0 < r < h - 1:
            candidates.append((min(r, h - 1 - r), "row", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and 0 < c < w - 1:
            candidates.append((min(c, w - 1 - c), "col", c))

    if not candidates:
        return [row[:] for row in grid]

    _, axis, k = max(candidates)
    if axis == "row":
        a = [row[:] for row in grid[:k]]
        b = [row[:] for row in grid[k + 1:]]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    from collections import Counter
    ca = Counter(x for row in a for x in row)
    cb = Counter(x for row in b for x in row)
    shared = set(ca) & set(cb)
    if not shared:
        return a

    color = max(shared, key=lambda x: ca[x] + cb[x])

    # A single shared-color cell in one panel is a fill cue.
    if ca[color] == 1 or cb[color] == 1:
        return [[color] * len(row) for row in a]

    out = []
    for r, row in enumerate(a):
        out.append([
            3 if row[c] == color and r < len(b) and c < len(b[r])
            and b[r][c] == color else color
            for c in range(len(row))
        ])
    return out
